mapper.select:
SELECT no,name,subject,hit,TO_CHAR(regdate,'yyyy-mm-dd hh24:mi:ss') as dbday, content,pwd
FROM board
WHERE no=#{no}

mapper.update:
UPDATE board SET
hit=hit+1
WHERE no=#{no}

mapper.select:
SELECT pwd
FROM board
WHERE no=#{no}

mapper.update:
UPDATE board SET
	name = #{name},
	subject = #{subject},
	content = #{content},
	pwd = #{pwd}
WHERE no=#{no}
